// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.POST(options.BaseURL+"/api/v1/auth/login", wrapper.Login)
	router.POST(options.BaseURL+"/api/v1/auth/logout", wrapper.Logout)
	router.GET(options.BaseURL+"/api/v1/auth/me", wrapper.GetMe)
	router.POST(options.BaseURL+"/api/v1/auth/password", wrapper.ChangePassword)
	router.POST(options.BaseURL+"/api/v1/auth/password-reset/request", wrapper.RequestPasswordReset)
	router.POST(options.BaseURL+"/api/v1/auth/password-reset/confirm", wrapper.ConfirmPasswordReset)
	router.GET(options.BaseURL+"/api/v1/users", wrapper.ListUsers)
	router.POST(options.BaseURL+"/api/v1/users", wrapper.CreateUser)
	router.POST(options.BaseURL+"/api/v1/users/:id/deactivate", wrapper.DeactivateUser)
	router.POST(options.BaseURL+"/api/v1/users/:id/reactivate", wrapper.ReactivateUser)
	router.PUT(options.BaseURL+"/api/v1/users/:id/roles", wrapper.SetUserRoles)
	router.POST(options.BaseURL+"/api/v1/users/:id/admin-membership", wrapper.GrantAdminMembership)
	router.POST(options.BaseURL+"/api/v1/users/:id/admin-membership/revoke", wrapper.RevokeAdminMembership)
	router.POST(options.BaseURL+"/api/v1/users/:id/password-reset", wrapper.ResetUserPassword)
}

